look.customCSS:
/* ───── 星野门扉 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/220px 260px,radial-gradient(ellipse at 50% 112%,#1F5A52 0 30%,transparent 55%),linear-gradient(180deg,#141433 0%,#1D2150 55%,#173E4A 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：不做框，往下淡出，底下一道细光线 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,rgba(20,20,51,.9),rgba(20,20,51,0)) !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;bottom:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(127,240,240,.8),transparent) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.15em !important}
[data-wk="headdim"]{color:#AFB4D8 !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#fff !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{flex:none !important;width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#fff !important}

/* 头像：一块石头门牌，上面圆孔里是头像，底下透出一道锁孔的光——像从锁孔里往外看 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important;box-shadow:0 0 0 2px #E8E0D4,0 0 14px 3px rgba(255,230,180,.55) !important;margin-bottom:12px !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-22% !important;right:-22% !important;top:-22% !important;bottom:-58% !important;border-radius:46% 46% 14px 14px / 40% 40% 14px 14px !important;background:radial-gradient(circle at 35% 25%,#8A827A,#5A5450 70%) !important;box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.15),0 4px 8px rgba(0,0,0,.45) !important;z-index:-1 !important;pointer-events:none !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;left:20% !important;right:20% !important;top:90% !important;height:46% !important;background:url("data:image/svg+xml;base64,") center top/100% 100% no-repeat !important;z-index:0 !important;pointer-events:none !important;filter:drop-shadow(0 0 4px rgba(255,220,150,.9)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before,[data-wk="chathead"] button[data-wk="avatar"]::after,[data-wk="chathead"] span[data-wk="avatar"]::after{content:none !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img[data-wk="avatar"]{margin-bottom:0 !important;box-shadow:0 0 0 2px #E8E0D4,0 0 10px 2px rgba(255,230,180,.5) !important}
[data-wk="msg"] [data-wk="row"]{gap:16px !important}

/* 气泡：一扇开着的门——深紫门框，门洞里透出光，门扇斜着开在一边，门底下几级发光台阶 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:2px !important;letter-spacing:.12em !important;font-weight:600 !important;padding:13px 22px !important;color:#3A2E5A !important;border:5px solid #3A3170 !important;box-shadow:inset 0 0 0 1.5px #241E4E,0 0 18px 4px rgba(255,214,190,.35) !important;margin-bottom:22px !important}
/* 他的：暖白粉的光，门扇在右，台阶往左下 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:radial-gradient(ellipse at 50% 50%,#FFFDF6,#FFE6D0 70%,#FFD3D8) !important;margin-right:20px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-24px !important;top:-6px !important;bottom:-6px !important;width:18px !important;height:auto !important;left:auto !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA4IDgnPjxjaXJjbGUgY3g9JzQnIGN5PSc0JyByPSczJyBmaWxsPScjRjJEMjhBJyBzdHJva2U9JyNCODkxM0UnIHN0cm9rZS13aWR0aD0nLjgnLz48L3N2Zz4=") 4px 55%/6px 6px no-repeat,url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:-30px !important;bottom:-28px !important;top:auto !important;right:auto !important;width:60px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;filter:drop-shadow(0 0 4px rgba(127,240,240,.8)) !important}
/* 我的：彩虹光，门扇在左，台阶往右下 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(110deg,#FFE3F1 0%,#FFF1C9 22%,#E2FFD8 42%,#D5F2FF 62%,#E6DBFF 82%,#FFE3F1 100%) !important;margin-left:20px !important;box-shadow:inset 0 0 0 1.5px #241E4E,0 0 20px 5px rgba(220,200,255,.45) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;left:-24px !important;top:-6px !important;bottom:-6px !important;width:18px !important;height:auto !important;right:auto !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA4IDgnPjxjaXJjbGUgY3g9JzQnIGN5PSc0JyByPSczJyBmaWxsPScjRjJEMjhBJyBzdHJva2U9JyNCODkxM0UnIHN0cm9rZS13aWR0aD0nLjgnLz48L3N2Zz4=") 9px 55%/6px 6px no-repeat,url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;right:-30px !important;bottom:-28px !important;top:auto !important;left:auto !important;width:60px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;filter:drop-shadow(0 0 4px rgba(127,240,240,.8)) !important}

/* 时间：一行淡色小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#AFB4D8 !important;letter-spacing:.3em !important;font-size:11.5px !important}
/* 已送达＝空心小圈；已读＝一颗亮起来的小星 */
[data-wk="meta"]{color:#AFB4D8 !important;font-size:11px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:8px !important;margin-top:-4px !important}
[data-wk="msg"][data-me="0"] [data-wk="meta"]{margin-left:42px !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{margin-right:42px !important}
[data-wk="meta"]::after{content:"" !important;width:11px !important;height:11px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PGNpcmNsZSBjeD0nNicgY3k9JzYnIHI9JzMuNCcgZmlsbD0nbm9uZScgc3Ryb2tlPScjQUZCNEQ4JyBzdHJva2Utd2lkdGg9JzEuMicvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{width:11px !important;height:15px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy02IC04IDEyIDE2Jz48cGF0aCBkPSdNMCAtNyBRLjYgLS42IDUgMCBRLjYgLjYgMCA3IFEtLjYgLjYgLTUgMCBRLS42IC0uNiAwIC03WicgZmlsbD0nI2ZmZicvPjwvc3ZnPg==") center/contain no-repeat !important;filter:drop-shadow(0 0 4px rgba(127,240,240,.95)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:radial-gradient(ellipse at 50% 50%,#FFFDF6,#FFE6D0 70%,#FFD3D8) !important;border:5px solid #3A3170 !important;border-radius:2px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#3A3170 !important}
[data-wk="name"]{color:#AFB4D8 !important}

/* 动描、我的动作：没有框，像门缝里漏出来的一道光——左边一道细光线，淡金斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:block !important;background:linear-gradient(90deg,rgba(255,230,180,.12),transparent 70%) !important;border:none !important;border-left:2px solid #FFE0A8 !important;border-radius:0 !important;box-shadow:none !important;color:#FFE9C8 !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.08em !important;padding:4px 0 4px 14px !important}
[data-wk="myactink"]{border-left:none !important;border-right:2px solid #7FF0F0 !important;padding:4px 14px 4px 0 !important;text-align:right !important;background:linear-gradient(270deg,rgba(127,240,240,.1),transparent 70%) !important;color:#D8FBFB !important}
[data-wk="narrbar"]{background:rgba(20,20,51,.95) !important;border-top:1px solid rgba(127,240,240,.4) !important}
[data-wk="narrkind"]{border:1px solid rgba(201,194,240,.5) !important;border-radius:999px !important;background:transparent !important;color:#AFB4D8 !important}
[data-wk="narrkind"][data-on="1"]{background:#7FF0F0 !important;border-color:#7FF0F0 !important;color:#141433 !important}
/* 系统提示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#AFB4D8 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnoteclose"]{color:#AFB4D8 !important}

/* 底栏：不做框，往上淡出，上沿一道细光线；输入框是一块淡紫玻璃；最右「让他回复」是一扇推开一半、透出光的门 */
[data-wk="composer"]{position:relative !important;background:linear-gradient(180deg,rgba(23,62,74,0),rgba(20,40,60,.9)) !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;top:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(127,240,240,.8),transparent) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.08) !important;border:1px solid rgba(201,194,240,.5) !important;border-radius:8px !important;color:#fff !important}
[data-wk="chatinput"]::placeholder{color:#AFB4D8 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:44px !important;min-width:44px !important;height:46px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 10px rgba(255,220,200,.75)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:rgba(20,20,51,.96) !important;border-top:1px solid rgba(127,240,240,.4) !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
/* ───── 星野门扉 · 第二批：卡片 ───── */
[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:linear-gradient(180deg,#2A2560,#1E1B48) !important;border:4px solid #3A3170 !important;border-radius:3px !important;box-shadow:inset 0 0 0 1.5px #5A4FA0,0 0 16px 3px rgba(127,240,240,.18) !important;color:#fff !important}
[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#fff !important;border-color:rgba(201,194,240,.35) !important}

/* 转账＝一把挂着小牌的金钥匙：收下了钥匙插进锁里转开、锁亮起来；退回了钥匙上划一道 */
[data-wk="transfercard"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#2A2560,#1E1B48) !important;border:4px solid #3A3170 !important;border-radius:3px !important;box-shadow:inset 0 0 0 1.5px #5A4FA0,0 0 16px 3px rgba(127,240,240,.18) !important;color:#fff !important;padding-left:78px !important}
[data-wk="transfercard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:50% !important;width:60px !important;height:40px !important;margin-top:-24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 5px rgba(242,210,138,.7)) !important}
[data-wk="transfercard"] *{color:#fff !important;border-color:rgba(201,194,240,.35) !important}
[data-wk="transferlabel"]{color:#AFB4D8 !important;letter-spacing:.2em !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#FFE9B8 !important;font-weight:700 !important;text-shadow:0 0 10px rgba(255,220,150,.6) !important}
[data-wk="transferrule"]{border:none !important;height:2px !important;background:repeating-linear-gradient(90deg,#7FF0F0 0 10px,transparent 10px 16px) !important;opacity:.7 !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(0,0,0,.2) !important}
[data-wk="transferbtn"]{border-radius:2px !important}
[data-wk="transferbtn"][data-part="take"]{background:linear-gradient(110deg,#FFE3F1,#FFF1C9 40%,#D5F2FF) !important;color:#3A2E5A !important;border:none !important;font-weight:700 !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;color:#fff !important;border:1px solid rgba(201,194,240,.6) !important}
[data-wk="transferseal"]{background:transparent !important;border:1px solid rgba(201,194,240,.6) !important;color:#fff !important;border-radius:4px !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="accepted"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:none !important;opacity:.6 !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.75 !important}

/* 红包＝一扇系着红丝带的小门；领完了门开了，光泼出来 */
[data-wk="rpcard"]{position:relative !important;overflow:visible !important;width:220px !important;min-height:88px !important;padding:16px 16px 16px 76px !important;background:linear-gradient(180deg,#2A2560,#1E1B48) !important;border:4px solid #3A3170 !important;border-radius:3px !important;box-shadow:inset 0 0 0 1.5px #5A4FA0,0 0 16px 3px rgba(127,240,240,.18) !important;color:#fff !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:50px !important;height:64px !important;margin-top:-34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpcard"]::after{content:"一扇门" !important;position:absolute !important;right:12px !important;bottom:6px !important;font-size:10px !important;letter-spacing:.25em !important;color:#AFB4D8 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"] > div:not([data-wk]){padding:0 !important;background:transparent !important}
[data-wk="rpmsg"]{-webkit-line-clamp:2 !important;color:#FFE9C8 !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 8px rgba(255,220,150,.8)) !important}
[data-wk="rpcard"][data-status="done"]::after{content:"门开了" !important}
/* 拆红包＝一扇大门：关着时是一整扇深紫木门（四块门板、金门把、门缝漏光），「开」是门上的锁孔；
   拆开后门扇转到一边，门洞里是一片暖光，金额站在光里，门底下接三级发光台阶 */
[data-wk="rpenvelope"]{position:relative !important;overflow:visible !important;border-radius:6px 6px 2px 2px !important}
[data-wk="rpenvelope"][data-stage="closed"]{background:radial-gradient(circle at 82% 52%,#F2D28A 0 7px,#B8913E 7.5px 9px,transparent 9.5px),linear-gradient(#2A2358,#2A2358) 50% 8%/76% 2px no-repeat,linear-gradient(90deg,transparent 12%,rgba(255,255,255,.07) 12% 44%,transparent 44% 56%,rgba(255,255,255,.07) 56% 88%,transparent 88%) center 14%/100% 30% no-repeat,linear-gradient(90deg,transparent 12%,rgba(255,255,255,.07) 12% 44%,transparent 44% 56%,rgba(255,255,255,.07) 56% 88%,transparent 88%) center 86%/100% 30% no-repeat,linear-gradient(180deg,#4A3F86,#3A3170) !important;border:8px solid #241E4E !important;box-shadow:0 0 0 2px #5A4FA0,0 0 22px 4px rgba(255,220,150,.55),0 0 60px 10px rgba(255,214,190,.25) !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="closed"] *{color:#FFE9C8 !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 0 10px rgba(255,220,150,.8)) !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpenvelope"][data-stage="open"]{background:radial-gradient(ellipse at 50% 60%,#FFFDF4,#FFE9C8 55%,#FFD3D8) !important;border:8px solid #3A3170 !important;box-shadow:0 0 0 2px #5A4FA0,0 0 40px 10px rgba(255,220,170,.6) !important}
[data-wk="rpenvelope"][data-stage="open"]::after{content:"" !important;position:absolute !important;right:-46px !important;top:-10px !important;bottom:-10px !important;width:40px !important;background:radial-gradient(circle at 40% 52%,#F2D28A 0 4px,transparent 4.5px),url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;pointer-events:none !important}
[data-wk="rpenvelope"][data-stage="open"]::before{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;bottom:-46px !important;height:38px !important;background:linear-gradient(#7FF0F0,#7FF0F0) center 4px/70% 4px no-repeat,linear-gradient(#7FF0F0,#7FF0F0) center 17px/84% 4px no-repeat,linear-gradient(#7FF0F0,#7FF0F0) center 30px/100% 4px no-repeat !important;filter:drop-shadow(0 0 6px rgba(127,240,240,.9)) !important;opacity:.9 !important;pointer-events:none !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#3A2E5A !important}
[data-wk="rpavatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #E8E0D4,0 0 12px rgba(255,230,180,.6) !important}
[data-wk="rpamount"]{color:#3A2E5A !important;background:none !important;text-shadow:0 0 14px rgba(255,255,255,.9) !important}
[data-wk="rpclose"]{background:transparent !important;border:1.5px solid #fff !important;color:#fff !important}
